import React, { useMemo, useState } from "react";
import { useApp } from "../../lib/AppContext";
import { formatLabel, statuses } from "../../lib/reportData";
import ReportsTable from "../../components/reports/ReportsTable";

const ReportsPage = () => {
  const { reports, notify } = useApp();
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState("All status");
  const [category, setCategory] = useState("All categories");
  const categories = [...new Set(reports.map((report) => report.category))];

  const filtered = useMemo(
    () =>
      reports.filter(
        (report) =>
          (status === "All status" || report.status === status) &&
          (category === "All categories" || report.category === category) &&
          `${report.id} ${report.location} ${report.description} ${report.category}`
            .toLowerCase()
            .includes(query.toLowerCase()),
      ),
    [reports, query, status, category],
  );

  const resetFilters = () => {
    setStatus("All status");
    setCategory("All categories");
    setQuery("");
  };

  return (
    <>
      <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
        <div>
          <div className="text-[9px] font-bold tracking-widest text-gray-400">
            CASE MANAGEMENT
          </div>
          <h1 className="my-2 font-['Manrope',sans-serif] text-2xl font-bold tracking-tight">
            Reports queue
          </h1>
          <p className="text-[11px] text-gray-500">
            Review, assign and track environmental cases.
          </p>
        </div>
        <button
          className="rounded-lg bg-[#185835] px-4 py-3 text-[11px] font-semibold text-white shadow-sm hover:bg-[#12472a]"
          onClick={() => notify("Report export prepared")}
        >
          ⇩ Export reports
        </button>
      </div>

      <div className="mb-4 grid grid-cols-2 overflow-hidden rounded-xl border border-gray-100 bg-white sm:grid-cols-4">
        {[
          [reports.length, "Total reports"],
          [reports.filter((report) => report.status === "SUBMITTED").length, "Awaiting review"],
          [reports.filter((report) => report.status === "IN_PROGRESS").length, "In progress"],
          [reports.filter((report) => report.status === "RESOLVED").length, "Resolved"],
        ].map(([value, label], index) => (
          <div
            className={`p-3.5 ${index < 2 ? "border-b sm:border-b-0" : ""} ${
              index % 2 === 0 ? "border-r" : "sm:border-r"
            } border-gray-100`}
            key={label}
          >
            <b className="block font-['Manrope',sans-serif] text-lg">{value}</b>
            <span className="text-[9px] text-gray-500">{label}</span>
          </div>
        ))}
      </div>

      <section className="overflow-hidden rounded-xl border border-gray-100 bg-white">
        <div className="flex flex-wrap items-center gap-2 border-b border-gray-100 p-3">
          <div className="flex h-9 min-w-full flex-1 items-center rounded-md border border-gray-200 px-2 text-gray-400 sm:min-w-[220px]">
            <span className="text-lg">⌕</span>
            <input
              className="w-full border-0 bg-transparent px-2 text-[10px] text-gray-700 outline-none"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search by case, location or keyword…"
            />
          </div>
          <select
            className="h-9 flex-1 rounded-md border border-gray-200 bg-white px-2 text-[10px] text-gray-600"
            value={status}
            onChange={(event) => setStatus(event.target.value)}
          >
            <option>All status</option>
            {statuses.map((value) => (
              <option key={value} value={value}>
                {formatLabel(value)}
              </option>
            ))}
          </select>
          <select
            className="h-9 flex-1 rounded-md border border-gray-200 bg-white px-2 text-[10px] text-gray-600"
            value={category}
            onChange={(event) => setCategory(event.target.value)}
          >
            <option>All categories</option>
            {categories.map((value) => (
              <option key={value}>{value}</option>
            ))}
          </select>
          <button
            className="h-9 rounded-md border border-gray-200 px-3 text-[10px] text-gray-600"
            onClick={resetFilters}
          >
            ↺ Reset
          </button>
        </div>

        <ReportsTable reports={filtered} />

        <div className="flex items-center justify-between border-t border-gray-100 px-3 py-3 text-[9px] text-gray-500">
          <span>
            Showing <b>{filtered.length ? `1–${filtered.length}` : 0}</b> of{" "}
            <b>{filtered.length}</b> reports
          </span>
          <div className="flex gap-1">
            <button
              className="rounded border border-gray-200 px-2 py-1"
              disabled
            >
              ← Previous
            </button>
            <button className="rounded bg-[#eaf2ed] px-2.5 py-1 font-bold text-[#185835]">
              1
            </button>
            <button
              className="rounded border border-gray-200 px-2 py-1"
              disabled
            >
              Next →
            </button>
          </div>
        </div>
      </section>
    </>
  );
};

export default ReportsPage;
